recs.append(R(9708016,"ویگن چاکلیٹ کوسا بریڈ [بغیر تیل یا چینی]",
"یہ ویگن چاکلیٹ زکینی بریڈ کیک جیسی لگتی ہے، لیکن اتنی چینی کے بغیر! کھجوریں اس لذیذ میٹھی چیز کو میٹھا کرتی ہیں اور سبزی کا کوئی بھی نشان چھپا دیتی ہیں!",
"12 قتلے (1 - 5\"x9\" لوف پین)","1 قتلہ",
[("خشک اجزاء","190 گرام اوٹ کا آٹا، تقریباً 2 کپ، پسند ہو تو گلوٹن سے پاک"),("خشک اجزاء","⅓ کپ کچا بغیر میٹھا کوکو پاؤڈر"),("خشک اجزاء","2.5 چائے کے چمچ بیکنگ پاؤڈر"),("خشک اجزاء","¼ چائے کا چمچ سمندری نمک"),
("گیلے اجزاء","1 کپ گٹھلی نکالی ہوئی کھجوریں، ٹھونس کر بھری ہوئی"),("گیلے اجزاء","¼ کپ پانی"),("گیلے اجزاء","2 چائے کے چمچ خالص ونیلا ایکسٹریکٹ"),("گیلے اجزاء","2 کپ کدوکش کی ہوئی کوسا، آہستگی سے بھری ہوئی، تقریباً 1 درمیانی کوسا (اپنے کچن سنک کے اوپر اضافی نمی نچوڑ لیں)"),("گیلے اجزاء","1 ¼ کپ بغیر میٹھا کیا ہوا کاجو کا دودھ یا اپنی پسند کا پودوں سے بنا دودھ"),
("اختیاری","⅓ کپ ڈارک چاکلیٹ چپس اور اگر چاہیں تو اوپر چھڑکنے کے لیے مزید")],
["اوون کو 350℉/176℃ پر پہلے سے گرم کریں اور 5\"x9\" لوف پین میں پارچمنٹ پیپر بچھا دیں۔",
"تمام خشک اجزاء ایک بڑے پیالے میں پھینٹ لیں اور الگ رکھ دیں۔",
"کھجوریں اور پانی فوڈ پروسیسر میں ڈالیں اور پیسٹ بننے تک پلس کریں، ضرورت کے مطابق اطراف سے کھرچتے رہیں۔ کھجور کا پیسٹ خشک اجزاء کے پیالے میں باقی تمام اجزاء کے ساتھ منتقل کریں، اگر چاکلیٹ چپس استعمال کر رہے ہیں تو ان سمیت۔ آٹے کے ذرات ختم ہونے تک ملائیں۔",
"آمیزہ اپنے تیار لوف پین میں ڈالیں۔ اگر چاہیں تو مزید چاکلیٹ چپس چھڑکیں اور آہستگی سے دبا دیں۔",
"50-55 منٹ بیک کریں، یا جب تک ٹوتھ پک زیادہ تر صاف نکلے۔ پھر اوون سے نکالیں اور قتلے کاٹنے سے پہلے مکمل ٹھنڈا ہونے کے لیے احتیاط سے کولنگ ریک پر منتقل کرنے سے پہلے کم از کم 10 منٹ ٹھنڈا ہونے دیں۔ لطف اٹھائیں!"],
["شروع کرنے سے پہلے اپنے اجزاء ناپیں اور تیار کریں۔ اس سے یقینی ہوگا کہ آپ کچھ نہ بھولیں، اور مراحل کے درمیان اجزاء تیار کرتے ہوئے جلدی میں محسوس نہ کریں۔","سب سے درست نتائج کے لیے آٹا تولیں۔ تھیلے سے آٹا چمچ بھر کر لینے سے اکثر بہت زیادہ آٹا استعمال ہو جاتا ہے، اور لوف کی بناوٹ بدل جائے گی۔ اگر آپ کو ناپنے والے کپ استعمال کرنے ہی پڑیں تو آٹا کپ میں چمچ سے ڈالیں، اور چھری کی پشت سے اضافی ہٹا دیں۔","کدوکش کی ہوئی کوسا کو کیک کے آمیزے میں ملانے سے پہلے پیالے میں یا اپنے کچن سنک کے اوپر اس کی اضافی نمی نچوڑ لیں۔","اپنے لوف پین میں پارچمنٹ پیپر استعمال کریں۔ اس سے نہ صرف بیک ہونے کے بعد لوف منتقل کرنا آسان ہوتا ہے بلکہ آپ اپنے پین کو چکنا کرنے سے بھی بچ سکتے ہیں۔","قتلے کاٹنے سے پہلے اپنی ویگن چاکلیٹ زکینی بریڈ کو کمرے کے درجہ حرارت تک مکمل ٹھنڈا کریں۔ ٹھنڈا ہونے کا وقت لوف کو جمنے میں مدد دیتا ہے اور قتلے کاٹنا آسان بناتا ہے۔","قتلے کاٹتے وقت ہموار، صاف ٹکڑوں کے لیے ہر کٹ کے درمیان اپنی چھری گیلی کریں۔","بچی ہوئی پلاسٹک ریپ میں ڈھکی ہوئی یا بند ڈبے میں کمرے کے درجہ حرارت پر 2-3 دن رہتی ہے۔ فریج میں 4-5 دن رکھیں، یا فریزر کے لیے موزوں ڈبے میں ہوا بند کر کے 3 ماہ تک منجمد کریں۔ آپ تیز اور آسان ناشتے یا اسنیکس کے لیے قتلے کر کے منجمد کر سکتے ہیں، یا لوف کو ثابت منجمد کر سکتے ہیں۔"],[]))
